CREATE OR REPLACE VIEW VLP_DP.BRONZE.V_RAW_VELOSHIP_SHIPMENTS
  COMMENT = 'RAW_VELOSHIP_SHIPMENTS with dedup flags (ADR 0004)'
AS
WITH ranked AS (
    SELECT
        r.*,
        ROW_NUMBER() OVER (PARTITION BY _KAFKA_TOPIC, _KAFKA_PARTITION, _KAFKA_OFFSET, _EVENT_ID
            ORDER BY _INSERTED_AT, _FILE_NAME, _FILE_ROW_NUMBER) AS _TECH_RN,
        FIRST_VALUE(_KAFKA_PARTITION) OVER (PARTITION BY _KAFKA_TOPIC, _EVENT_ID ORDER BY _KAFKA_TS, _KAFKA_PARTITION, _KAFKA_OFFSET, _INSERTED_AT) AS _FIRST_PARTITION,
        FIRST_VALUE(_KAFKA_OFFSET) OVER (PARTITION BY _KAFKA_TOPIC, _EVENT_ID ORDER BY _KAFKA_TS, _KAFKA_PARTITION, _KAFKA_OFFSET, _INSERTED_AT) AS _FIRST_OFFSET
    FROM VLP_DP.BRONZE.RAW_VELOSHIP_SHIPMENTS r
)
SELECT
    * EXCLUDE (_TECH_RN, _FIRST_PARTITION, _FIRST_OFFSET),
    _EVENT_ID IS NOT NULL AND _TECH_RN > 1 AS _IS_TECH_DUP,
    _EVENT_ID IS NOT NULL AND NOT (EQUAL_NULL(_KAFKA_PARTITION, _FIRST_PARTITION)
        AND EQUAL_NULL(_KAFKA_OFFSET, _FIRST_OFFSET)) AS _IS_RESEND
FROM ranked;
GRANT SELECT ON VIEW VLP_DP.BRONZE.V_RAW_VELOSHIP_SHIPMENTS TO ROLE VLP_TRANSFORMER;

