CREATE OR REPLACE VIEW VLP_DP.BRONZE.V_GL_BATCH_COMPLETENESS
  COMMENT = 'GL extract batches: rows received vs announced in the header vlp_batch_count (ADR 0004)'
AS
SELECT
    _SOURCE_TXN_ID AS BATCH_ID,
    ANY_VALUE(BK_COMPANY_CODE) AS COMPANY_CODE,
    ANY_VALUE(BK_PERIOD) AS PERIOD,
    COUNT(DISTINCT _SOURCE_TXN_SEQ) AS ROWS_RECEIVED,
    MAX(_SOURCE_TXN_COUNT) AS ROWS_EXPECTED,
    COUNT(DISTINCT _SOURCE_TXN_SEQ) = MAX(_SOURCE_TXN_COUNT) AS IS_COMPLETE,
    MIN(_KAFKA_TS) AS FIRST_ROW_TS,
    MAX(_KAFKA_TS) AS LAST_ROW_TS
FROM VLP_DP.BRONZE.V_RAW_GL_EXTRACT
WHERE NOT _IS_TECH_DUP AND NOT _IS_RESEND
GROUP BY _SOURCE_TXN_ID;
GRANT SELECT ON VIEW VLP_DP.BRONZE.V_GL_BATCH_COMPLETENESS TO ROLE VLP_TRANSFORMER;
